/**
 * generated by stackra gen from src/routes/<name>/ (every *.route.ts and *.layout.ts with the page,
 * error and fallback files bound by name), src/panels/*.panel.ts, src/config/i18n.config.ts (URL
 * prefixes) and the resources, documents and settings pages of the consumed manifests — do not
 * edit
 * Purpose: the full React Router 7 route tree from the route and layout classes, nested under
 *          their layouts, with the panel routes gen derived from the consumed resources, documents
 *          and settings pages in the same layout, mounted once per locale prefix under the root
 *          error boundary `@stackra/navigation` owns.
 * Boundary: code-based routes; a hand-written route config is banned. `toRoot` mounts the tree at
 *           `/` for the default locale and at each lowercase prefix (`/en-us`, `/ar`, `/ar-sa`) for
 *           the others, and wraps it in the navigation package's boundary (UI from `@stackra/ui`,
 *           reports through the errors package's reporter port); the console ships no boundary of
 *           its own and no route customises one. `toRoute` binds a class's options and members
 *           (loader, submit, meta) and the files beside it to the router; each page is a class
 *           component gen compiled to a function. `document:` routes resolve the tenant's
 *           published version through `GetDocumentQuery` and fall back to the class. The server
 *           re-checks permission on every call. `DashboardRoute` replaces the panel's generated
 *           index route for `tenant_admin` (reported). `OfflineRoute` is also prerendered per
 *           locale (`vite.config.ts` `prerender`).
 * Runtime: browser
 */
import type { RouteObject } from "react-router";
import {
  toLayout,
  toPanel,
  toResource,
  toRoot,
  toRoute,
  toSettingsPage,
} from "@stackra/navigation/react";
import { Resources } from "#stackra/resources";
import { SettingsPages } from "#stackra/settings";
import { prefixes } from "#stackra/i18n";
import { CustomerPortalPanel } from "#src/panels/customer-portal.panel";
import { DashboardRoute } from "#src/routes/dashboard/dashboard.route";
import { Dashboard } from "#src/routes/dashboard/dashboard";
import { MobileLinkRoute } from "#src/routes/mobile-link/mobile-link.route";
import { MobileLink } from "#src/routes/mobile-link/mobile-link";
import { NotFoundRoute } from "#src/routes/not-found/not-found.route";
import { NotFound } from "#src/routes/not-found/not-found";
import { OfflineRoute } from "#src/routes/offline/offline.route";
import { Offline } from "#src/routes/offline/offline";
import { OpenFileRoute } from "#src/routes/open-file/open-file.route";
import { OpenFile } from "#src/routes/open-file/open-file";
import { OpenRoute } from "#src/routes/open/open.route";
import { PublicLayout } from "#src/routes/public/public.layout";
import { Public } from "#src/routes/public/public";
import { QuickOrderRoute } from "#src/routes/quick-order/quick-order.route";
import { QuickOrder } from "#src/routes/quick-order/quick-order";
import { SettingsRoute } from "#src/routes/settings/settings.route";
import { Settings } from "#src/routes/settings/settings";
import { ShareRoute } from "#src/routes/share/share.route";
import { Share } from "#src/routes/share/share";
import { ShellLayout } from "#src/routes/shell/shell.layout";
import { Shell } from "#src/routes/shell/shell";
import { SignInRoute } from "#src/routes/sign-in/sign-in.route";
import { SignIn } from "#src/routes/sign-in/sign-in";
import { WelcomeRoute } from "#src/routes/welcome/welcome.route";

/**
 * The navigation-owned root boundary, then the layouts under every locale prefix; declared routes
 * in declaration order, generated panel routes, the catch-all last.
 */
export const routes: RouteObject[] = toRoot({ prefixes }, [
  toLayout(PublicLayout, { component: Public }, [
    toRoute(SignInRoute, { component: SignIn }),
    // prerendered per locale and precached; served by the worker when the shell is missing
    toRoute(OfflineRoute, { component: Offline }),
  ]),
  // /portal: the panel's own shell with what the consumed manifests list in the app area
  toPanel(CustomerPortalPanel),
  toLayout(ShellLayout, { component: Shell }, [
    // index; shadows the generated dashboard index route
    toRoute(DashboardRoute, { component: Dashboard }),
    toRoute(QuickOrderRoute, { component: QuickOrder }),
    toRoute(SettingsRoute, { component: Settings }),
    // document: WelcomeDocument → GetDocumentQuery({ key: "console.welcome" }) or the class
    toRoute(WelcomeRoute),
    // /open?url=: the PWA protocol handler and the desktop deep link land here; no page
    toRoute(OpenRoute),
    // the PWA share target (the worker redirects its POST here) and the file handler
    toRoute(ShareRoute, { component: Share }),
    toRoute(OpenFileRoute, { component: OpenFile }),
    // the mobile app's universal links without the app: redirects, or the notice page
    toRoute(MobileLinkRoute, { component: MobileLink }),
    ...toResource(Resources.Product), // /catalogue/products, /:id, /:id/edit, /new
    ...toResource(Resources.ProductCollection), // /catalogue/collections, /:id/edit, /new
    ...toResource(Resources.Order), // /orders/orders, /:id
    ...toResource(Resources.LoyaltyAccount), // /loyalty/accounts, /:id, /new
    ...toResource(Resources.AccessLogEntry), // /access-log/entries
    ...toResource(Resources.FailedJob), // /queue/failed-jobs
    ...toResource(Resources.SalesOverview), // /sales
    ...toSettingsPage(SettingsPages.orders), // /settings/orders
    ...toSettingsPage(SettingsPages.inventory), // /settings/inventory
    ...toSettingsPage(SettingsPages.loyalty_kit), // /settings/loyalty-kit
    ...toSettingsPage(SettingsPages.messages), // /settings/messages (user scope)
    toRoute(NotFoundRoute, { component: NotFound }),
  ]),
]);
